// create an activity event
const event = new nsActEvent(
  displayText,
  aSrcFolder.server,
  statusText,
  Date.now(), // start time
  Date.now()
); // completion time

event.addSubject(aSrcFolder);
event.addSubject(aDestFolder);
event.iconClass = aMove ? "moveMail" : "copyMail";

this.activityMgr.addActivity(event);
